/** Small real files, embedded so the demo and tests need no disk access. */

/** Decode an embedded base64 fixture into its original bytes. */
const base64 = (text: string) =>
  Uint8Array.from(atob(text), char => char.charCodeAt(0))

/** A 1x1 transparent PNG: signature, IHDR, IDAT, IEND. */
export const tinyPng = base64(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="
)

/** A 64-bit little-endian x86-64 executable with .text and .shstrtab sections. */
export const tinyElf = base64(
  ""
)

/** A stored (uncompressed) archive holding hello.txt and dir/notes.md. */
export const tinyZip = base64(
  ""
)
